-- Phase 5: communications, patient communication policy, durable outbox/inbox, and scheduling concurrency guards.
CREATE TABLE IF NOT EXISTS patient_communication_preferences (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,sms_enabled BOOLEAN NOT NULL DEFAULT true,email_enabled BOOLEAN NOT NULL DEFAULT true,whatsapp_enabled BOOLEAN NOT NULL DEFAULT false,opted_out_all BOOLEAN NOT NULL DEFAULT false,timezone TEXT NOT NULL DEFAULT 'UTC',updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE (clinic_id, patient_id));
CREATE TABLE IF NOT EXISTS communications (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,appointment_id TEXT REFERENCES appointments(id) ON DELETE SET NULL,workflow_run_id TEXT REFERENCES workflow_runs(id) ON DELETE SET NULL,channel TEXT NOT NULL CHECK (channel IN ('sms','email','whatsapp')),direction TEXT NOT NULL CHECK (direction IN ('inbound','outbound')),status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','queued','sending','sent','delivered','failed','cancelled','blocked')),subject TEXT,body TEXT NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 10000),template_key TEXT,provider_reference TEXT,failure_class TEXT,idempotency_key TEXT NOT NULL,correlation_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ,delivered_at TIMESTAMPTZ,UNIQUE (clinic_id, idempotency_key));
CREATE TABLE IF NOT EXISTS communication_events (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,communication_id TEXT NOT NULL REFERENCES communications(id) ON DELETE CASCADE,event_type TEXT NOT NULL,provider_reference TEXT,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,event_type TEXT NOT NULL,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','published','failed')),attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),available_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_error TEXT,idempotency_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE (clinic_id, idempotency_key));
CREATE TABLE IF NOT EXISTS inbound_events (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT REFERENCES clinics(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_event_id TEXT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,processed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE (provider, provider_event_id));
CREATE INDEX IF NOT EXISTS idx_comm_preferences_clinic_patient ON patient_communication_preferences(clinic_id,patient_id); CREATE INDEX IF NOT EXISTS idx_communications_clinic_created ON communications(clinic_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_communications_clinic_status ON communications(clinic_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_communications_patient ON communications(patient_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_communication_events_communication ON communication_events(communication_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_outbox_pending ON outbox_events(status,available_at,created_at); CREATE INDEX IF NOT EXISTS idx_inbound_events_clinic ON inbound_events(clinic_id,created_at DESC);
ALTER TABLE patient_communication_preferences ENABLE ROW LEVEL SECURITY; ALTER TABLE patient_communication_preferences FORCE ROW LEVEL SECURITY; ALTER TABLE communications ENABLE ROW LEVEL SECURITY; ALTER TABLE communications FORCE ROW LEVEL SECURITY; ALTER TABLE communication_events ENABLE ROW LEVEL SECURITY; ALTER TABLE communication_events FORCE ROW LEVEL SECURITY; ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY; ALTER TABLE outbox_events FORCE ROW LEVEL SECURITY; ALTER TABLE inbound_events ENABLE ROW LEVEL SECURITY; ALTER TABLE inbound_events FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS phase5_comm_pref_select ON patient_communication_preferences; DROP POLICY IF EXISTS phase5_comm_pref_write ON patient_communication_preferences; CREATE POLICY phase5_comm_pref_select ON patient_communication_preferences FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY phase5_comm_pref_write ON patient_communication_preferences FOR ALL TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS phase5_communications_select ON communications; DROP POLICY IF EXISTS phase5_communications_write ON communications; CREATE POLICY phase5_communications_select ON communications FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY phase5_communications_write ON communications FOR ALL TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS phase5_communication_events_select ON communication_events; DROP POLICY IF EXISTS phase5_communication_events_write ON communication_events; CREATE POLICY phase5_communication_events_select ON communication_events FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY phase5_communication_events_write ON communication_events FOR INSERT TO authenticated WITH CHECK (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS phase5_outbox_select ON outbox_events; DROP POLICY IF EXISTS phase5_outbox_write ON outbox_events; CREATE POLICY phase5_outbox_select ON outbox_events FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY phase5_outbox_write ON outbox_events FOR ALL TO authenticated USING (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS phase5_inbound_select ON inbound_events; DROP POLICY IF EXISTS phase5_inbound_write ON inbound_events; CREATE POLICY phase5_inbound_select ON inbound_events FOR SELECT TO authenticated USING (clinic_id IS NOT NULL AND clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY phase5_inbound_write ON inbound_events FOR INSERT TO authenticated WITH CHECK (clinic_id IS NOT NULL AND clinic_id IN (SELECT id FROM clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
REVOKE ALL ON patient_communication_preferences,communications,communication_events,outbox_events,inbound_events FROM anon; GRANT SELECT,INSERT,UPDATE,DELETE ON patient_communication_preferences TO authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON communications TO authenticated; GRANT SELECT,INSERT ON communication_events TO authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON outbox_events TO authenticated; GRANT SELECT,INSERT ON inbound_events TO authenticated;
CREATE OR REPLACE FUNCTION public.prevent_appointment_overlap() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE conflict_id TEXT; BEGIN IF NEW.status IN ('scheduled','confirmed') THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.clinic_id || ':' || coalesce(NEW.provider_id,'') || ':' || NEW.patient_id,0)); SELECT a.id INTO conflict_id FROM appointments a WHERE a.clinic_id=NEW.clinic_id AND a.id<>NEW.id AND a.status IN ('scheduled','confirmed') AND (a.patient_id=NEW.patient_id OR (NEW.provider_id IS NOT NULL AND a.provider_id=NEW.provider_id)) AND a.appointment_datetime < NEW.appointment_datetime + (NEW.duration_minutes * interval '1 minute') AND NEW.appointment_datetime < a.appointment_datetime + (a.duration_minutes * interval '1 minute') LIMIT 1; IF conflict_id IS NOT NULL THEN RAISE EXCEPTION 'appointment overlap with %', conflict_id USING ERRCODE='23P01'; END IF; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS appointment_overlap_guard ON appointments; CREATE TRIGGER appointment_overlap_guard BEFORE INSERT OR UPDATE OF clinic_id,patient_id,provider_id,appointment_datetime,duration_minutes,status ON appointments FOR EACH ROW EXECUTE FUNCTION public.prevent_appointment_overlap();
